import type { Metadata } from "next";
import { urlFor } from "@/sanity/lib/image";
import type { Seo, SanityImage } from "@/sanity/lib/types";

export const SITE_URL = (process.env.NEXT_PUBLIC_SITE_URL ?? "http://localhost:3000").replace(/\/$/, "");
export const SITE_NAME = "Shift to Zero Carbon";
export const SITE_DESCRIPTION =
  "Pioneering the next era of industrial decarbonization. We bridge the gap between heavy industry and environmental stewardship.";

/** Generated by app/og/route.tsx. Used when a page has no image of its own. */
const DEFAULT_OG_IMAGE = { url: "/og", width: 1200, height: 630, alt: SITE_NAME };

export const absoluteUrl = (path: string) => `${SITE_URL}${path === "/" ? "" : path}`;

export const shareImageUrl = (image?: SanityImage) =>
  image?.asset ? urlFor(image).width(1200).height(630).fit("crop").url() : undefined;

type PageMetadataInput = {
  /** Canonical path, e.g. "/events/climate-week". */
  path: string;
  title?: string;
  description?: string;
  image?: SanityImage;
  /** Editor overrides from Sanity. They win over the page's own title, description and image. */
  seo?: Seo;
  type?: "website" | "article";
  publishedTime?: string;
  /** Skip the "%s | Shift to Zero Carbon" template (the home page). */
  absoluteTitle?: boolean;
};

/**
 * Full metadata for a public page. Next.js merges `openGraph` and `twitter` shallowly, so every
 * page sets them completely here instead of relying on the root layout.
 */
export function pageMetadata({
  path,
  title,
  description,
  image,
  seo,
  type = "website",
  publishedTime,
  absoluteTitle,
}: PageMetadataInput): Metadata {
  const t = seo?.title || title;
  const d = seo?.description || description;
  const imageUrl = shareImageUrl(seo?.image) ?? shareImageUrl(image);
  const images = imageUrl ? [{ url: imageUrl, width: 1200, height: 630 }] : [DEFAULT_OG_IMAGE];

  return {
    // Leave title/description out when unset so the layout defaults apply.
    ...(t && { title: absoluteTitle ? { absolute: t } : t }),
    ...(d && { description: d }),
    alternates: { canonical: path },
    openGraph: {
      type,
      siteName: SITE_NAME,
      locale: "en_US",
      url: path,
      title: t ?? SITE_NAME,
      description: d ?? SITE_DESCRIPTION,
      images,
      ...(publishedTime && { publishedTime }),
    },
    twitter: {
      card: "summary_large_image",
      title: t ?? SITE_NAME,
      description: d ?? SITE_DESCRIPTION,
      images: images.map((i) => i.url),
    },
  };
}

/** The organization, referenced by `@id` from other JSON-LD blocks. */
export const ORGANIZATION_ID = `${SITE_URL}/#organization`;
